BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "新五代史·卷67·吴越世家·章德安等将领", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/536806e05eea577781a96322d189bed7fc5e7ec1/content/books/zizhi-tongjian/vol-283/year-0943/part-03/sources/library/xinwudaishi-067-wuyue-generals/source.txt", "note": "《新五代史》卷67·吴越世家·章德安等将领，段落 xin-wudaishi-b08f244b9241-p003372；已核上下文及传主，纸本及异文待核。", "id": "74db9c66-c82b-5c13-b386-bee7c29954d4"}, {"title": "新五代史·卷68·闽世家·陈光逸谏死", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/536806e05eea577781a96322d189bed7fc5e7ec1/content/books/zizhi-tongjian/vol-283/year-0943/part-03/sources/library/xinwudaishi-068-chen-guangyi/source.txt", "note": "《新五代史》卷68·闽世家·陈光逸谏死，段落 xin-wudaishi-b08f244b9241-p003410；已核上下文及传主，纸本及异文待核。", "id": "4b3860b5-4c90-58fa-8710-577459834ded"}, {"title": "新五代史·卷68·闽世家·王倓被辱尸", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/536806e05eea577781a96322d189bed7fc5e7ec1/content/books/zizhi-tongjian/vol-283/year-0943/part-03/sources/library/xinwudaishi-068-wang-tan-grave/source.txt", "note": "《新五代史》卷68·闽世家·王倓被辱尸，段落 xin-wudaishi-b08f244b9241-p003408；已核上下文及传主，纸本及异文待核。", "id": "ad52a7f5-9781-5859-bbb8-6073a5187e1e"}, {"title": "资治通鉴·卷283·天福八年·四五月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0492098592de640119d51b379b17908f65b59b0/content/books/zizhi-tongjian/vol-283/year-0943/part-02/sources/library/tongjian-283-943-april-may/source.txt", "note": "《资治通鉴》卷283·天福八年·四五月及追述，段落 zizhi-tongjian-a63549944a71-p003367；已核上下文及传主，纸本及异文待核。", "id": "8e1284b2-bd81-5ec3-9d02-501f6839c4d0"}, {"title": "新五代史·卷65·南汉世家·刘晟继位", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0492098592de640119d51b379b17908f65b59b0/content/books/zizhi-tongjian/vol-283/year-0943/part-02/sources/library/xinwudaishi-065-liu-sheng-accession/source.txt", "note": "《新五代史》卷65·南汉世家·刘晟继位，段落 xin-wudaishi-b08f244b9241-p003281；已核上下文及传主，纸本及异文待核。", "id": "ac3719db-7597-59f3-ad72-ea42a782a2d1"}, {"title": "新五代史·卷9·晋出帝本纪·天福八年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-009-943-return/source.txt", "note": "《新五代史》卷9·晋出帝本纪·天福八年，段落 xin-wudaishi-b08f244b9241-p000334；已核上下文及传主，纸本及异文待核。", "id": "8b6277d6-bc14-525d-a7c0-ae15a89bdca9"}, {"title": "新五代史·卷62·南唐世家·李璟与诸弟", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-062-jing-brothers/source.txt", "note": "《新五代史》卷62·南唐世家·李璟与诸弟，段落 xin-wudaishi-b08f244b9241-p003137；已核上下文及传主，纸本及异文待核。", "id": "4eec6cb7-f426-58dc-9677-661a25ec2fce"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "陈望", "aliases": ["陳望"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政部将。942年与包洪实率水军抵御福州军，七月丁酉在尤口与对方交战。生卒年未载。", "biography": null, "status": "draft", "id": "1129ee15-bc93-5f0e-bb19-5143390129ac"}, {"name": "潘承祐", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "镇武军节度判官，晋江人。王延羲与王延政交战时，多次劝王延政停战修好；王延政向闽王使者展示军队、言语傲慢时，潘承祐长跪劝谏，受到威胁仍继续进谏。具体年月及生卒年未载。", "biography": null, "status": "draft", "id": "709be4ea-d9bd-5e7a-b136-9452103cf994"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "刘弘杲", "aliases": ["劉弘杲", "刘洪杲", "劉洪杲"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘杲，获封王爵之子。", "biography": null, "status": "draft", "id": "eb7c29f2-2022-5446-97aa-43b3b6d75ad8"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘思潮", "aliases": ["劉思潮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉力士。943年在刘弘熙安排下，由陈道庠召入晋王府练习手搏；随后参与杀死刘弘度，刘弘熙即位后受到赏赐。《新五代史》还记刘思潮等获封功臣。生卒年尚未核。", "biography": null, "status": "draft", "id": "d7493fd7-d448-5c67-8a8d-eb273df31b0a"}, {"name": "谭令禋", "aliases": ["譚令禋"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉力士，943年在刘弘熙安排下，由陈道庠召入晋王府练习手搏。史书将他列于五名力士中；陈道庠、刘思潮等随后杀死刘弘度，但本段没有逐一说明所有力士当时的动作。生卒年尚未核。", "biography": null, "status": "draft", "id": "0e89825f-b852-5c2e-a140-9238c42a0625"}, {"name": "刘弘昌", "aliases": ["劉弘昌", "刘洪昌", "劉洪昌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘昌，获封王爵之子。", "biography": null, "status": "draft", "id": "fda27388-00bf-5390-90ae-9604e2ec1c33"}, {"name": "刘弘弼", "aliases": ["劉弘弼", "刘洪弼", "劉洪弼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘弼，获封王爵之子。", "biography": null, "status": "draft", "id": "dcf1aa4f-270b-5fb0-bf60-4a3911672aad"}, {"name": "王继鹏", "aliases": ["王繼鵬", "王昶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王继鹏，被任命权军府事的王子。", "biography": null, "status": "draft", "id": "94e0308c-1642-5beb-9233-76f848fff4f0"}, {"name": "王倓", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国同平章事，曾在王继鹏宴席上说新罗所献宝剑可以斩不忠的人，王延羲听后变色。王倓死后，王延羲在943年条下因又见献剑而命掘墓辱尸。《资治通鉴》后句转录为校冢，据同段前文与《新五代史》王倓明确校核主体，原字保留。生卒年月尚未核。", "biography": null, "status": "draft", "id": "1f754534-1c62-5d64-90df-2db47136309c"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "陈光逸", "aliases": ["陳光逸"], "era": "五代十国", "birth_year": null, "death_year": 943, "description": "闽国校书郎。943年条下记他不顾朋友劝阻，上书列王延羲五十项罪恶，随后被鞭打并悬吊致死。《新五代史》作五十余事，鞭打次数也有差异，两书分别保留。出生年未载。", "biography": null, "status": "draft", "id": "10b73de1-6bf0-5c2d-86e1-665bb64d69e4"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "钱弘佐", "aliases": ["錢弘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲许氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "0d604e68-f71f-5263-9e8f-80de6e9feb32"}, {"name": "阚璠", "aliases": ["闞璠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "明州人，吴越上统军使。钱弘佐初立时，史书说他排斥异己，钱弘佐不能制约；943年章德安、李文庆被贬后，他与胡进思更为专横。人物评价按史书归属保留，生卒年尚未核。", "biography": null, "status": "draft", "id": "b40418a5-918a-53c4-a5aa-4618d7fc7cd6"}, {"name": "章德安", "aliases": ["章徳安"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越内都监，处州人。941年钱传瓘临终时，建议让年轻的钱弘佐继位，并受托辅佐。钱传瓘死后，暂不公布死讯，与诸将商议后拘杀被告谋立钱弘侑的戴恽。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "cf63861a-a3c1-5d02-bf95-1f9e4631550f"}, {"name": "李文庆", "aliases": ["李文慶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "睦州人，吴越内牙右都监使。因不依附阚璠，943年七月乙巳被贬到睦州。生卒年未载。", "biography": null, "status": "draft", "id": "1af4a26d-2354-5e27-b0dd-3182caa04494"}, {"name": "胡进思", "aliases": ["胡進思"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "湖州人，吴越右统军使。943年条下记章德安与李文庆被贬后，史书称他与阚璠更加专横。生卒年尚未核。", "biography": null, "status": "draft", "id": "4f56160f-2b15-5a0c-9fa8-9523947bb1df"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "徐景遂", "aliases": ["景遂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐景遂，获任者。", "biography": null, "status": "draft", "id": "cb45cc6e-58fb-5804-8c3d-962cbbc03a13"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "李弘冀", "aliases": ["弘冀", "李冀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李璟的长子。943年七月条下被立为南昌王。姓名在《资治通鉴》作弘冀，《新五代史》同一册封作冀；沿用同一主体，不因姓名省写再建李冀。生卒年尚未核。", "biography": null, "status": "draft", "id": "e4027731-d3e9-5cd1-8c58-d504f38025da"}, {"name": "万景忻", "aliases": ["萬景忻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉将领。《新五代史》记942年与陈道庠在钱帛馆奋战，帮助刘弘昌、刘弘杲突围。生卒年未载。", "biography": null, "status": "draft", "id": "b3501eea-231e-526f-aac3-50b11c0becbb"}, {"name": "张遇贤", "aliases": ["張遇賢"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "博罗县吏。942年循州起事者拥立他为领袖，他称中天八国王、改元永乐并置官。南汉派刘弘昌、刘弘杲征讨，二人在钱帛馆被围，后由将领救出。生卒年未载。", "biography": null, "status": "draft", "id": "508b1255-a234-507d-a64f-ede078d1c559"}, {"name": "贾匡浩", "aliases": ["賈匡浩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "贾公铎的儿子，南唐百胜节度使。943年张遇贤转向虔州时，史书说他未作防备，部属接连战败，虔州城门白昼也关闭。生卒年未载。", "biography": null, "status": "draft", "id": "fb58e23e-a7f5-5dd0-ada5-25a575ae24da"}, {"name": "贾公铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：贾公铎。", "biography": null, "status": "draft", "id": "242f59ca-4d96-5fa7-8b74-51765b84a300"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

